def bisect(f, lo, hi, tol=1e-9):
    # f(lo) and f(hi) must have opposite signs
    while hi - lo > tol:
        mid = (lo + hi) / 2
        if f(lo) * f(mid) <= 0:
            hi = mid
        else:
            lo = mid
    return (lo + hi) / 2

def trapezoid(f, a, b, n=100):
    h = (b - a) / n
    total = (f(a) + f(b)) / 2
    for k in range(1, n):
        total += f(a + k * h)
    return total * h

def newton(f, df, x, steps=8):
    for _ in range(steps):
        x = x - f(x) / df(x)
    return x

